import {
  BaseButton,
  createStyles,
  GradientContainer,
  Text,
  useTheme,
} from '@core/ui';
import React, { useState, useCallback } from 'react';
import { useChangeLanguage, UserData, useTranslation } from '@core/service';
import { Image, ScrollView, StyleSheet, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { icArrow } from '@src/assets/images';
import { BlurView } from '@react-native-community/blur';
import { handlePushMiniApp } from '@src/presentation/navigation/Utils';
import { isEmpty } from 'lodash';

type CTAButtonWelcomePropsType = {
  data: CTAButtonType;
  hasSession?: boolean;
  userData?: UserData;
};

type CTAButtonType = {
  order: string;
  id: number;
  label: string;
  icon: string;
  destination?: string;
  label_color?: string;
  label_font: string;
  background_color?: string;
  label_2?: string;
  label_font_2?: string;
  label_color_2?: string;
};
const CTAButtonWelcome: React.FC<CTAButtonWelcomePropsType> = (props) => {
  const { theme } = useTheme();
  const { data, hasSession, userData } = props;
  const { t, i18n } = useTranslation(['headerBar']);

  const insets = useSafeAreaInsets();
  const styles = useStyles();
  const onLogin = () => {
    handlePushMiniApp('open_app', {
      appName: 'AuthApp',
      screen: 'LoginUsername',
    });
  };
  return (
    <BaseButton style={[styles.container]}>
      <BlurView style={styles.absolute} blurAmount={24} blurType="light" />
      <Image source={{ uri: data?.icon }} style={styles.icon} />
      <View style={styles.content}>
        <Text
          style={[
            styles.label,
            data?.label_color && { color: data?.label_color },
            data?.label_font && { fontFamily: data?.label_font },
          ]}
        >
          {!isEmpty(userData) && userData?.INDI?.name? `Chào buổi sáng ${userData?.INDI?.name}` : data?.label}
        </Text>
      </View>

      {!hasSession && !isEmpty(userData)? (
        <BaseButton style={styles.buttonLoginStyle} onPress={onLogin}>
          <Text style={[styles.textButton]}>{t('login')}</Text>
        </BaseButton>
      ): (
        <Image style={styles.iconArrow} source={icArrow} />
      )}
    </BaseButton>
  );
};
const useStyles = createStyles((theme) => ({
  container: {
    width: '100%',
    paddingHorizontal: theme.Size.ms(16),
    gap: theme.Size.Horizontal.Medium,
    paddingVertical: theme.Size.ms(18),
    justifyContent: 'center',
    flexDirection: 'row',
    alignItems: 'center',
    borderRadius: theme.BorderRadius.md,
    backgroundColor: theme.Colors.Background.White + '99',
  },
  buttonLoginStyle: {
    backgroundColor: theme.Colors.Background.Neutral200,
    padding: theme.Scaling.ms(8),
    borderRadius: theme.Scaling.ms(1000),
    justifyContent: 'center',
    alignItems: 'center',
  },
  content: {
    gap: theme.Size.Horizontal.Small,
    flex: 1,
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
  },
  textButton: {
    ...theme.Typography.TextCaption100.Bold,
  },
  iconArrow: {
    width: theme.Size.Horizontal.xLarge,
    height: theme.Size.Vertical.xLarge,
  },
  icon: {
    width: theme.Size.ModerateHorizontal.xxxLarge,
    height: theme.Size.ModerateHorizontal.xxxLarge,
  },
  label: {
    ...theme.Typography.TextSubheadline.Bold,
  },
  absolute: {
    ...StyleSheet.absoluteFillObject,
    backgroundColor: 'transparent',
    borderRadius: theme.BorderRadius.md,
  },
}));
export { CTAButtonWelcome };
export type { CTAButtonWelcomePropsType, CTAButtonType };
