import React, {
  FC,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
} from 'react';
import {
  Image,
  ScrollView,
  SectionList,
  Text,
  TouchableOpacity,
  View,
} from 'react-native';

import { BaseButton, SearchBar, createStyles, useTheme } from '@core/ui';
import {
  menuList,
  MenuItemType,
  MenuItemGroupType,
  dataFooter,
  emojiList,
  sideMenuDefault,
  NAVIGATION_CONFIG,
} from '../constants';
import MenuItem from './items/MenuItem';
import { MinusIcon, PlusIcon } from '@src/assets';
import { isEmpty } from 'lodash';
import { ListSocial } from './commons';
import {
  SafeAreaView,
  useSafeAreaInsets,
} from 'react-native-safe-area-context';
import WrapperAccount from './commons/WrapperAccount/WrapperAccount';
import {
  eventBusService,
  Storage,
  STORAGE_KEY,
  UserService,
} from '@core/service';
import { Palette } from '@src/theme/palette/palette.light';
import { DrawerContentComponentProps } from '@react-navigation/drawer';

type SectionType = {
  title: string;
  icon: string | null;
  data: MenuItemType[]; // Đảm bảo data là một mảng các menu items
  after?: boolean;
  before?: boolean;
};

export type CustomDrawerContentProps = {
  selectedMenuTop: number;
  drawerProps: DrawerContentComponentProps;
};

const CustomDrawerContent: FC<CustomDrawerContentProps> = (props) => {
  const { selectedMenuTop, drawerProps } = props;
  const styles = useStyles();
  const { theme } = useTheme();
  const insets = useSafeAreaInsets();
  const [expandedSections, setExpandedSections] = useState<string>('');

  // const navigation =
  //   useNavigation<NativeStackNavigationProp<MainStackParamList>>();
  const [isLogin, setIsLogin] = useState(false);
  const [user, setUser] = useState({});

  const sectionListRef = useRef<SectionList>(null);

  useEffect(() => {
    const listenLogin = eventBusService.on('auth.login_success', () => {
      setIsLogin(true);
    });
    const listenLogout = eventBusService.on('auth.logout_success', () => {
      setIsLogin(false);
    });

    return () => {
      listenLogin.remove();
      listenLogout.remove();
    };
  }, []);

  useEffect(() => {
    UserService.getUser().then((user) => {
      setUser(user);
      if (!isEmpty(user)) {
        setIsLogin(true);
      }
    });
  }, [isLogin]);

  useEffect(() => {
    setExpandedSections(menuList[0].menu_item_group[selectedMenuTop + 1].name);
  }, [selectedMenuTop]);

  const sections = useMemo<SectionType[]>(() => {
    return (
      [...menuList[0].menu_item_group, ...sideMenuDefault].flatMap((group) => {
        if (!group || !group.menu_items) return [];

        return {
          title: group.name ?? '',
          icon: group.icon ?? null,
          data: group.menu_items.map((item) => ({
            ...item,
            order: Number(item.order),
          })),
          after: 'after' in group ? group.after : true,
          before: 'before' in group ? group.before : true,
        };
      }) ?? []
    );
  }, []);

  const toggleSection = useCallback(
    (title: string, length: number, index: number) => {
      if (length > 0) {
        if (title === expandedSections) {
          setExpandedSections('');
        } else {
          setExpandedSections(title);

          // Cuộn đến vị trí tiêu đề
          sectionListRef.current?.scrollToLocation({
            sectionIndex: index,
            itemIndex: 0,
            animated: true,
            viewOffset: theme.Scaling.ms(50), // Điều chỉnh khoảng cách nếu cần
          });
        }
        return;
      }

      const configFunction = NAVIGATION_CONFIG[title];
      if (configFunction) {
        const config = configFunction();
        config.action();
      }
    },
    [expandedSections],
  );

  const renderItem = useCallback(
    (item: MenuItemType, index: number, section: any) => {
      return (
        <MenuItem
          index={index}
          item={item}
          sectionTitle={section.title}
          expandedSections={expandedSections}
          drawerProps={drawerProps}
          isLastItem={index === section.data.length - 1}
        />
      );
    },
    [expandedSections, drawerProps, user],
  );

  const renderSectionHeader = useCallback(
    ({
      title,
      data,
      icon,
      after,
      before,
      index,
    }: {
      title: string;
      data: MenuItemType[];
      icon: string | null;
      after?: boolean;
      before?: boolean;
      index: number;
    }) => {
      const shouldRender = isEmpty(user) ? after : before;

      return (
        <>
          {shouldRender && (
            <TouchableOpacity
              onPress={() => toggleSection(title ?? '', data?.length, index)}
              style={[
                styles.wrapperTitle,
                isEmpty(icon) && styles.justifyBetween,
              ]}
            >
              {!isEmpty(icon) && (
                <Image source={{ uri: icon ?? '' }} style={styles.imageStyle} />
              )}
              <Text
                style={
                  (styles.titleStyle,
                  !isEmpty(icon)
                    ? theme.Typography.TextBody.Regular
                    : theme.Typography.TextBody.SemiBold)
                }
              >
                {title}
              </Text>
              {data?.length > 0 &&
                (expandedSections === title ? <MinusIcon /> : <PlusIcon />)}
            </TouchableOpacity>
          )}
        </>
      );
    },

    [
      expandedSections,
      styles.imageStyle,
      styles.justifyBetween,
      styles.titleStyle,
      styles.wrapperTitle,
      theme.Typography.TextBody.Regular,
      theme.Typography.TextBody.SemiBold,
      user,
      toggleSection,
    ],
  );

  const ListFooterComponent = useCallback(() => {
    return (
      <>
        <View style={styles.wrapperEmoji}>
          <Text
            style={styles.textRatingStyle}
          >{`Bạn có hài lòng với trải nghiệm, trên ứng dụng Di-HDBank?`}</Text>
          <ScrollView
            horizontal
            style={styles.emojiListStyle}
            contentContainerStyle={{ justifyContent: 'center', flexGrow: 1 }}
          >
            {emojiList.map((item) => {
              return (
                <TouchableOpacity>
                  <Image source={item ?? ''} style={styles.emojiStyle} />
                </TouchableOpacity>
              );
            })}
          </ScrollView>
        </View>
        {!isEmpty(user) && (
          <BaseButton onPress={onLogout} style={styles.wrapperButtonLogoout}>
            <Text style={styles.textLogoutStyle}>Đăng xuất</Text>
          </BaseButton>
        )}
        <View style={styles.wrapperFoooter}>
          <ListSocial textStyle={styles.titleSocialStyle} />
          <Text style={styles.textFooterStyle}>
            {dataFooter.footer + `\nPhiên bản 1.0.1`}
          </Text>
          <TouchableOpacity
            onPress={() =>
              drawerProps.navigation.navigate('WebViewScreen', {
                url: 'www.hdbank.com.vn',
                title: '',
              })
            }
          >
            <Text style={styles.textLinkStyle}>{`www.hdbank.com.vn`}</Text>
          </TouchableOpacity>
          <View
            style={{
              height: insets.bottom + theme.Scaling.ms(220),
            }}
          />
        </View>
      </>
    );
  }, [
    insets.bottom,
    styles.textFooterStyle,
    styles.titleSocialStyle,
    styles.wrapperFoooter,
    theme.Scaling,
    user,
    isLogin,
  ]);

  const onLogout = () => {
    Storage.clear(STORAGE_KEY.USER_AUTH);
    Storage.clear(STORAGE_KEY.ID_TOKEN);
    eventBusService.emit('auth.logout_success');
    drawerProps?.navigation.closeDrawer();
  };

  return (
    <SafeAreaView>
      <View style={styles.container}>
        <WrapperAccount user={user} />
        <SearchBar
          isOutlined
          style={styles.wrapperSearch}
          placeholder="Tìm kiếm"
        />
        <SectionList
          ref={sectionListRef}
          sections={sections}
          keyExtractor={(item, index) => index?.toString()}
          renderItem={({ item, index, section }) =>
            renderItem(item, index, section)
          }
          stickySectionHeadersEnabled={false}
          showsVerticalScrollIndicator={false}
          renderSectionHeader={({
            section: { data, title, icon, after, before },
            index,
          }) => {
            return renderSectionHeader({
              title: title ?? '',
              data: data as MenuItemType[],
              icon: icon,
              after,
              before,
              index,
            });
          }}
          ListFooterComponent={ListFooterComponent}
        />
      </View>
    </SafeAreaView>
  );
};

export default CustomDrawerContent;
// export default memo(CustomDrawerContent, areEqualMemo);

