import { NativeModules, Platform } from "react-native";

const LINKING_ERROR =
    "The package '@hdbsdk/react-native-cgf' doesn't seem to be linked. Make sure: \n\n" +
    Platform.select({ ios: "- You have run 'pod install'\n", default: "" }) +
    "- You rebuilt the app after installing the package\n";

export const ReactNativeCGF = NativeModules.ReactNativeCGF
    ? NativeModules.ReactNativeCGF
    : new Proxy(
        {},
        {
            get() {
                throw new Error(LINKING_ERROR);
            },
        }
    );

export const launchCGF = async (data: object) => {
    try {
        const result = await ReactNativeCGF.launchCGF(data);
        return result;
    } catch (error) {
        throw error;
    }
};

