import {
  configureStore,
  type ThunkAction,
  type Action,
} from '@reduxjs/toolkit';
import {
  useSelector as useReduxSelector,
  useDispatch as useReduxDispatch,
  type TypedUseSelectorHook,
} from 'react-redux';
import { reducer } from './rootReducer';
import { middleware } from './middleware';

const store = configureStore({
  reducer,
  middleware: (getDefaultMiddleware) =>
    getDefaultMiddleware().concat(middleware),
});

const useDispatch = () => useReduxDispatch<ReduxDispatch>();

const useSelector: TypedUseSelectorHook<ReduxState> = useReduxSelector;

type ReduxStore = typeof store;

type ReduxState = ReturnType<typeof store.getState>;

type ReduxDispatch = typeof store.dispatch;

type ReduxThunkAction<ReturnType = void> = ThunkAction<
  ReturnType,
  ReduxState,
  unknown,
  Action
>;

export type { ReduxStore, ReduxState, ReduxDispatch, ReduxThunkAction };

export { store, useDispatch, useSelector };
