import {
    BaseButton,
    createStyles,
    GradientContainer,
    Text,
    useTheme,
  } from '@core/ui';
  import React, { useState, useCallback, useEffect } from 'react';
  import { eventBusService, useChangeLanguage, UserData, UserService, useTranslation } from '@core/service';
  import { Image, ScrollView, StyleSheet, View } from 'react-native';
  import { useSafeAreaInsets } from 'react-native-safe-area-context';
  import { icArrow } from '@src/assets/images';
  import { BlurView } from '@react-native-community/blur';
import { CTAButtonWelcome } from './CTAButtonWelcome';
import { CTAButtonWelcomeLogin } from './CTAButtonWelcomeLogin';
import { isEmpty, set } from 'lodash';
import moment from 'moment';
  
  type CTAButtonWelcomeHomePropsType = {
    data: CTAButtonType;
  };
  
  type CTAButtonType = {
    order: string;
    id: number;
    label: string;
    icon: string;
    destination?: string;
    label_color?: string;
    label_font: string;
    background_color?: string;
    label_2?: string;
    label_font_2?: string;
    label_color_2?: string;
  };
  const CTAButtonWelcomeHome: React.FC<CTAButtonWelcomeHomePropsType> = (props) => {
    const { theme } = useTheme();
    const { data } = props;
    const { t, i18n } = useTranslation(['CTAButtonWelcome']);
    const [isLogin, setIsLogin] = useState(false);
    const [userData, setUserData] = useState<UserData>({});
    const [hasSession, setHasSession] = useState(false);
    const [checkUser, setCheckUser] = useState(0);
  useEffect(() => {
    const listenLogin = eventBusService.on(
      'auth.login_success',
      () => {
        setIsLogin(true)
        setCheckUser(checkUser + 1)
      },
    );
    const listenLogout = eventBusService.on(
      'auth.logout_success',
      () => {
        setIsLogin(false)
        setCheckUser(checkUser + 1)
      },
    );

    return () => {
      listenLogin.remove();
      listenLogout.remove();
    };
  }, []);
  useEffect(() => {
    UserService.getUser().then((user) => {
      const isCorp = (user?.CORP?.length ?? 0) > 0;
      const isIndi = !!user?.INDI;
      const corpSegment = isCorp ? 'CORP' : null;
      const indiSegment = isIndi ? 'INDI' : null;
      const segment = corpSegment ?? indiSegment ?? '';
      if (!isEmpty(user)) {
        setIsLogin(true)
        setUserData(user);
        const expired = moment.unix(user?.exp).isBefore(moment());
        console.log('expired', expired) 
        setHasSession(!expired);
      }
      else {
        setIsLogin(false)
        setUserData({});
        setHasSession(false);
      }
    });
  }, [checkUser]);
    const insets = useSafeAreaInsets();
    const styles = useStyles();
    return (
        isLogin && !isEmpty(userData) && hasSession ? <CTAButtonWelcomeLogin data={data}/> : <CTAButtonWelcome hasSession={hasSession} userData={userData} data={data}/>
    );
  };
  const useStyles = createStyles((theme) => ({
    
  }));
  export { CTAButtonWelcomeHome };
  