import { createAsyncThunk } from '@reduxjs/toolkit';
import { TYPES } from '@src/di/types/types';
import { container } from '@src/di/inversify.config';
import { Query } from '@src/domain/models/query';
import { GetHomepageQuery } from '@src/application/homepage/queries/get_homepage/get_homepage_query';
import { GetHomepageHandler } from '@src/application/homepage/queries/get_homepage/get_homepage_handler';

export const fetchHomepage = createAsyncThunk(
  'homepage/fetch',
  async (request: GetHomepageQuery) => {
    const homepage = container.get<GetHomepageHandler>(TYPES.GetHomepageHandler);

    const query = new Query({
      query: { latitude: request.latitude, longitude: request.longitude },
    });
    return await homepage.handle(query);
  },
);
