import { BaseButton, createStyles, Text, useTheme } from '@core/ui';
import React, { useState, useCallback } from 'react';
import {
  eventBusService,
  OpenAppPayload,
  useChangeLanguage,
  useTranslation,
  UserService,
  STORAGE_KEY,
  Storage
} from '@core/service';
import { Image, ScrollView, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { HomePageMenu, MenuItem } from '@src/domain/entities/homepage';
import { handlePushMiniApp } from '@src/presentation/navigation/Utils';
import { launchCGF, launchLoan } from '@src/modules';

type HomePageMenuItemProps = {
  item: MenuItem;
  index: number;
};

interface IUserInfo {
  phone: string;
  clientNo: string;
  userId: string;
}

const getClientInfo = async (): Promise<IUserInfo | null> => {
  const user = await UserService.getUser()
  var userInfo = user?.INDI;
  if (!userInfo) {
    return user?.CORP?.find(u => (typeof u?.clientNo === 'string' && u?.clientNo.length > 0)) as IUserInfo;
  }
  return userInfo as IUserInfo;
};

const HomePageMenuItem: React.FC<HomePageMenuItemProps> = (props) => {
  const { theme } = useTheme();
  const { item, index } = props;
  const { t, i18n } = useTranslation(['HomePageMenuItem']);
  const styles = useStyles();

  const insets = useSafeAreaInsets();
  const backgroundColorDummy = [
    '#DA2128',
    '#FA6C1A',
    '#FAA61A',
    '#FFDD00',
    '#BCF126',
  ];
  const onPress = async () => {
    let userInfo = await getClientInfo();
    const accessToken = await Storage.retrieve(STORAGE_KEY.ID_TOKEN);
    const baseUrl = 'https://di-bank-uat.hdbank.com.vn/';
    if (!userInfo) {
      return;
    }

    if (item?.id == 1531 || item?.id == 1525) {
      handlePushMiniApp('open_app', {
        appName: 'BillPaymentApp',
      });
    } else if (item?.id == 1524) {
      handlePushMiniApp('open_app', {
        appName: 'TransferApp',
      });
    } else if (item?.id == 301) {
      launchLoan({ accessToken: accessToken, baseUrl: baseUrl, clientNo: userInfo?.clientNo, userId: userInfo?.userId, phoneNumber: userInfo?.phone, userRole: 'ROLIND' });
    }
    else if (item?.id === 305) {
      launchCGF({ accessToken: accessToken, baseUrl: baseUrl, clientNo: userInfo?.clientNo, userId: userInfo?.userId, phoneNumber: userInfo?.phone, userRole: 'ROLIND' });
    }
  };
  return (
    <BaseButton onPress={onPress} style={styles.container}>
      <Image style={styles.image} source={{ uri: item.icon }} />
      <Text
        style={[styles.label, item.label_color && { color: item.label_color }]}
      >
        {item.label}
      </Text>
    </BaseButton>
  );
};
const useStyles = createStyles((theme) => ({
  container: {
    gap: theme.Size.Vertical.Small,
    alignItems: 'center',
    maxWidth: (theme.Size.DEVICE_WIDTH - 2 * theme.Size.Horizontal.Medium) / 5,
  },
  label: {
    ...theme.Typography.TextCaption100.SemiBold,
    textAlign: 'center',
  },
  icon: {
    justifyContent: 'center',
    alignItems: 'center',
    width: theme.Size.Horizontal.Huge,
    height: theme.Size.Vertical.Huge,
    borderRadius: theme.BorderRadius.lg,
  },
  image: {
    width: theme.Size.Horizontal.Huge,
    height: theme.Size.Vertical.Huge,
  },
}));
export { HomePageMenuItem };
