import {
  BaseButton,
  createStyles,
  Text,
  useTheme,
} from '@core/ui';
import React, { useState, useCallback } from 'react';
import { useChangeLanguage, useTranslation } from '@core/service';
import { Image, ScrollView, View } from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { LeftMenuItem } from './LeftMenuItem';
import { icVolumeMuted, icVolumeUp } from '@src/assets/images';
import { LeftMenu as LeftMenuType} from '@src/domain/entities/homepage';

const leftMenuData = require('@src/presentation/homepage/HomepageInfo/defaultConfig/homepageleftmenu.json');

type LeftMenuPropsType = {
  data: LeftMenuType[];
  isMuteVideo: boolean;
  setMuteVideo: () => void;
}
const LeftMenu: React.FC<LeftMenuPropsType> = (props) => {
  const { data, setMuteVideo, isMuteVideo } = props;
  const { theme } = useTheme();
  const { t, i18n } = useTranslation(['LeftMenu']);
  const styles = useStyles();
  const [isPersional, setIsPersional] = useState(true);
  const insets = useSafeAreaInsets();
  const [muted, setIsMuteVideo] = useState(isMuteVideo);
  const handleMuteVideo = useCallback(() => {
    setMuteVideo(!muted);
    setIsMuteVideo(!muted);
  }, [muted]);
  return (
    <>
      <ScrollView showsVerticalScrollIndicator={false} nestedScrollEnabled={true} style={[styles.container]} contentContainerStyle={styles.contentContainerStyle} >
        {data?.map((item: LeftMenuType, index: number) => {
          return (
            <LeftMenuItem item={item} index={index} key={item.id} />
          );
        })}
      </ScrollView >
      <BaseButton hitSlop={{ top: 5, bottom: 5, left: 5, right: 5 }} onPress={handleMuteVideo} style={styles.btnVolume}>
        <Image source={muted ? icVolumeMuted : icVolumeUp} style={styles.logoVolume} />
      </BaseButton>
    </>
  );
};
const useStyles = createStyles(theme => ({
  container: {
    maxHeight: theme.Size.ModerateHorizontal.Titanic + theme.Size.ModerateHorizontal.Base,
    maxWidth: theme.Size.Horizontal.Enormous,
  },
  contentContainerStyle: {
    gap: 6,
    paddingVertical: theme.Size.ModerateHorizontal.Base,
  },
  logoVolume: {
    width: theme.Size.ModerateHorizontal.xxLarge,
    height: theme.Size.ModerateHorizontal.xxLarge,
  },
  btnVolume: {
    marginHorizontal: theme.Size.Horizontal.Medium,
    width: theme.Size.Horizontal.xxLarge,
    height: theme.Size.ModerateHorizontal.xxLarge,
  },
}));
export { LeftMenu };
