type PageSectionsPropsType = {
  item: HpProductSection;
  index: number;
  isMuteVideo: boolean;
  isPauseVideo?: boolean;
}
const PageSections: React.FC<PageSectionsPropsType> = (props) => {
  const { theme } = useTheme();
  // const { t, i18n } = useTranslation(['PageSections']);
  const { item, index, isMuteVideo, isPauseVideo } = props;
  const insets = useSafeAreaInsets();
  const styles = useStyles();
  const [isLogin, setIsLogin] = useState(false);
  const [isPersonal, setIsPersonal] = useState(true);
  const [currentPage, setCurrentPage] = useState(0);
  const handlePagination = (page) => {
    setCurrentPage(page);
  };

  return (
    <View style={{ ...StyleSheet.absoluteFillObject }}>
      <PageScroll
        dataVideo={item?.attributes.hp_product_section_backgrounds?.data}
        isMuteVideo={isMuteVideo}
        indexHorizontal={currentPage}
        setIndexHorizontal={setCurrentPage}
        isPauseVideo={isPauseVideo}
      />
      <View style={[styles.page, { bottom: theme.Size.ms(56) + 76 + insets.bottom }]}>
        <SectionsTitle item={item?.attributes} />

        <View  >
          <Pagination
            currentPage={currentPage}
            setCurrentPage={handlePagination}
            totalPages={item?.attributes.hp_product_section_backgrounds?.data?.length}
          />
          <CTAButton data={item?.attributes.hp_product_section_backgrounds?.data?.[currentPage]?.attributes?.cta_button}  />
        </View>
        <HomePageCard data={item?.attributes.hp_product_cards?.data?.[currentPage]} />
      </View>
    </View>
  );
};
