import React, { FC, useCallback, useMemo } from 'react';

import { useNavigation } from '@react-navigation/native';
import {
  Image,
  ImageStyle,
  Text,
  TextStyle,
  TouchableOpacity,
  View,
  ViewStyle,
} from 'react-native';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import { createStyles } from '@core/ui';
import { Palette } from '@src/theme/palette/palette.dark';
import { icBack } from '@src/assets';

type HeaderProps = {
  text?: string;
  style?: ViewStyle;
  textStyle?: TextStyle;
  rightIconStyle?: ImageStyle;
  leftIcon?: React.ReactNode;
  rightIcon?: React.ReactNode;
  type?: string;
  onPressLeft?: () => void;
  onPressRight?: () => void;
  leftIconStyle?: ImageStyle;
  leftIconBackStyle?: ImageStyle;
  disableBack?: boolean;
  disableRight?: boolean;
  hideRightComponent?: boolean;
};

export const Header: FC<HeaderProps> = (props) => {
  const {
    text,
    style,
    textStyle,
    leftIcon,
    rightIcon,
    onPressLeft,
    onPressRight,
    rightIconStyle,
    leftIconStyle,
    leftIconBackStyle,
    disableBack,
    disableRight,
    type,
    hideRightComponent,
  } = props;

  const styles = useStyles(props);
  const inset = useSafeAreaInsets();
  let navigation = useNavigation();

  const handleGoBack = useCallback(() => {
    onPressLeft ? onPressLeft() : navigation.goBack();
  }, [navigation, onPressLeft]);

  const leftComponent = useMemo(() => {
    return leftIcon ? (
      <TouchableOpacity
        style={[styles.iconBackStyle, leftIconStyle]}
        onPress={onPressLeft}
      >
        {leftIcon}
      </TouchableOpacity>
    ) : !disableBack ? (
      <TouchableOpacity
        style={[styles.iconBackStyle, leftIconBackStyle]}
        onPress={handleGoBack}
      >
        <Image source={icBack} style={styles.imageStyle} />
      </TouchableOpacity>
    ) : null;
  }, [
    disableBack,
    handleGoBack,
    leftIcon,
    leftIconBackStyle,
    leftIconStyle,
    onPressLeft,
    styles.iconBackStyle,
  ]);

  const rightComponent = useMemo(() => {
    return (
      <TouchableOpacity
        style={styles.rightButton}
        onPress={onPressRight}
        disabled={disableRight}
      >
        <View style={[styles.iconStyle, rightIconStyle]}>
          {rightIcon && rightIcon}
        </View>
      </TouchableOpacity>
    );
  }, [
    disableRight,
    onPressRight,
    rightIcon,
    rightIconStyle,
    styles.iconStyle,
    styles.rightButton,
  ]);

  return (
    <View style={[styles.container, { paddingTop: inset.top + 8 }, style]}>
      {leftComponent}
      <View style={styles.centerText}>
        <Text style={[styles.textStyle, textStyle]} numberOfLines={1}>
          {text}
        </Text>
      </View>
      {!hideRightComponent && rightComponent}
    </View>
  );
};

const useStyles = createStyles((theme) => ({
  container: {
    flexDirection: 'row',
    backgroundColor: Palette.white,
    paddingBottom: theme.Size.ModerateVertical.Regular,
    ...theme.Shadow.Shadow300,
  },
  imageStyle: {
    width: theme.Size.ms(40),
    height: theme.Size.ms(40),
  },
  centerText: {
    flex: 8,
    justifyContent: 'center',
    alignSelf: 'center',
  },
  iconStyle: {
    alignSelf: 'flex-end',
    justifyContent: 'center',
  },
  textStyle: {
    fontSize: theme.Size.ms(16),
    fontWeight: 'bold',
    color: Palette.black,
    textAlign: 'center',
  },
  iconBackStyle: {
    flex: 1,
    paddingLeft: theme.Size.ModerateHorizontal.Regular,
    alignSelf: 'center',
  },
  rightButton: {
    flex: 1,
    flexDirection: 'column',
    paddingRight: theme.Size.ModerateHorizontal.Medium,
    justifyContent: 'center',
  },
}));
