import React, { useCallback } from 'react';
import { View } from 'react-native';

import type { CheckBoxProps } from './ChoiceProps';
import {
  BaseButton,
  HighlightText,
  ICheckedBox,
  IIndeterminate,
  createStyles,
  useTheme,
} from '@core/ui';

const CheckBox: React.FC<CheckBoxProps> = ({
  checked,
  title,
  onPress,
  containerStyle,
  highlightStyle,
  onHighlightPress,
  size = 'small',
  isIndeterminate = false,
  isDisable = false,
}) => {
  const { theme } = useTheme();

  const styles = useStyles();

  const checkboxSize =
    size === 'large'
      ? theme.Size.Horizontal.xLarge
      : theme.Size.Horizontal.Medium;

  const _checkBoxColor = () => {
    if (isDisable) {
      return theme.Colors.ButtonBackground.Disable;
    }

    if (checked) {
      return theme.Colors.Main.Red;
    }

    return theme.Colors.Border.Neutral300;
  };

  const _buildCheckBox = () => {
    if (isIndeterminate && checked) {
      return (
        <IIndeterminate
          fill={_checkBoxColor()}
          width={checkboxSize}
          height={checkboxSize}
        />
      );
    }
    if (checked) {
      return (
        <ICheckedBox
          fill={_checkBoxColor()}
          width={checkboxSize}
          height={checkboxSize}
        />
      );
    }
    return ICheckbox();
  };

  const ICheckbox = useCallback(() => {
    return (
      <View
        style={[
          {
            height: checkboxSize,
            width: checkboxSize,
          },
          styles.checkbox,
        ]}
      />
    );
  }, [checkboxSize, styles.checkbox]);

  return (
    <BaseButton
      disabled={isDisable}
      onPress={onPress}
      style={[styles.container, containerStyle]}
    >
      {_buildCheckBox()}
      <HighlightText
        style={styles[size]}
        highlightStyle={highlightStyle}
        text={title}
        onPress={onHighlightPress}
      />
      {_buildCheckBox()}
    </BaseButton>
  );
};

export { CheckBox };

const useStyles = createStyles((theme) => ({
  container: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  checkbox: {
    borderRadius: theme.Size.ms(5),
    borderColor: theme.Colors.Text.Neutral500,
    borderWidth: theme.Size.ms(2),
  },
  small: {
    ...theme.Typography.TextCaption100.Regular,
    paddingLeft: theme.Size.Horizontal.Base,
  },
  large: {
    ...theme.Typography.TextSubheadline.Regular,
    paddingLeft: theme.Size.Horizontal.Base,
  },
}));
